// Alegra no documenta la forma exacta de lo que manda el webhook, así que aquí
// no confiamos en ella: buscamos el id donde pueda venir y con ese id volvemos
// a preguntarle a Alegra la factura completa.

const crudo = (items[0] && items[0].json) || {};
const cuerpo = crudo.body !== undefined ? crudo.body : crudo;
const base = Array.isArray(cuerpo) ? cuerpo[0] || {} : cuerpo;

const posibles = [
  base.id,
  base.invoiceId,
  base.idInvoice,
  base.data && base.data.id,
  base.invoice && base.invoice.id,
  base.resource && base.resource.id,
  base.payload && base.payload.id,
];

const facturaId = posibles
  .map((v) => (v === undefined || v === null ? '' : String(v).trim()))
  .find((v) => v !== '');

if (!facturaId) {
  throw new Error(
    'No encontré el id de la factura en lo que mandó Alegra. Esto fue lo que llegó: ' +
      JSON.stringify(cuerpo).slice(0, 500)
  );
}

return [{ json: { facturaId } }];

// Dejamos la factura en un formato parejo para poder revisarla, y sacamos el id
// del cliente para ir a traer su historial.

const f = (items[0] && items[0].json) || {};

const nombreDe = (p) => {
  const n = p && p.name;
  if (Array.isArray(n)) return n.filter(Boolean).join(' ');
  if (n && typeof n === 'object') return [n.firstName, n.lastName].filter(Boolean).join(' ');
  return n || 'Cliente sin nombre';
};

const cliente = f.client || {};

// La identificación llega como texto suelto o dentro de identificationObject.
const identificacion = String(
  cliente.identification ||
    (cliente.identificationObject && cliente.identificationObject.number) ||
    ''
).trim();

const lineas = (Array.isArray(f.items) ? f.items : []).map((it) => {
  const precio = Number(
    typeof it.price === 'object' && it.price !== null ? it.price.price : it.price
  ) || 0;
  const cantidad = Number(it.quantity ?? 0);
  const descuento = Number(it.discount ?? 0);
  return {
    nombre: String(it.name || it.reference || 'Ítem sin nombre'),
    precio,
    cantidad,
    descuento,
    bruto: precio * cantidad,
  };
});

return [
  {
    json: {
      facturaId: String(f.id),
      numero: String((f.numberTemplate && f.numberTemplate.fullNumber) || f.number || f.id),
      // Si la factura no trae cliente usamos 0, que no existe: el historial
      // llega vacío y el flujo sigue con las demás revisiones.
      clienteId:
        cliente.id === undefined || cliente.id === null || cliente.id === ''
          ? '0'
          : String(cliente.id),
      cliente: nombreDe(cliente),
      identificacion,
      fecha: f.date ? String(f.date).slice(0, 10) : '',
      vence: f.dueDate ? String(f.dueDate).slice(0, 10) : '',
      total: Number(f.total ?? 0),
      estado: String(f.status || ''),
      moneda: (f.currency && f.currency.code) || 'COP',
      lineas,
    },
  },
];

// Alegra devuelve máximo 30 facturas de proveedor por llamada, así que el nodo
// anterior hace varias llamadas y entrega una página por cada una.
// Aquí las abrimos para quedar con una factura por item.

const facturas = [];

for (const item of items) {
  const cuerpo = item.json;
  if (Array.isArray(cuerpo)) {
    facturas.push(...cuerpo);
  } else if (Array.isArray(cuerpo.data)) {
    facturas.push(...cuerpo.data);
  } else {
    facturas.push(cuerpo);
  }
}

return facturas.map((factura) => ({ json: factura }));

// ─── Puedes cambiar esto ──────────────────────────────────────────────
const DESCUENTO_MAXIMO = 20;        // porcentaje de descuento que ya te parece mucho
const VECES_SOBRE_EL_PROMEDIO = 3;  // 3 = avisa si la factura vale 3 veces lo normal
const MINIMO_HISTORIAL = 3;         // facturas anteriores que hacen falta para comparar
const TOPE_CLIENTE_NUEVO = 5000000; // monto alto para un cliente sin historial
const MONEDA = 'COP';
// ──────────────────────────────────────────────────────────────────────

const f = $('Preparar la revisión').first().json;

const plata = (n) =>
  new Intl.NumberFormat('es-CO', {
    style: 'currency',
    currency: MONEDA,
    maximumFractionDigits: 0,
  }).format(n);

const fecha = (d) => {
  if (!d) return null;
  const x = new Date(String(d).slice(0, 10) + 'T00:00:00');
  return isNaN(x.getTime()) ? null : x;
};

// El historial del cliente, sin contar esta misma factura ni las anuladas.
const historial = items
  .map((i) => i.json)
  .filter(
    (x) =>
      x &&
      String(x.id) !== String(f.facturaId) &&
      String(x.status || '').toLowerCase() !== 'void'
  )
  .map((x) => Number(x.total ?? 0))
  .filter((t) => t > 0);

const promedio = historial.length
  ? historial.reduce((s, t) => s + t, 0) / historial.length
  : 0;

const alertas = [];

// 1. Cliente sin identificación. Sin eso la factura no sirve para nada tributario.
if (!f.identificacion) {
  alertas.push('El cliente no tiene identificación registrada.');
}

// 2. Descuento alto en alguna línea.
const conDescuento = f.lineas.filter((l) => l.descuento > DESCUENTO_MAXIMO);
if (conDescuento.length) {
  alertas.push(
    'Descuento del ' +
      Math.max(...conDescuento.map((l) => l.descuento)) +
      '% en ' +
      (conDescuento.length === 1
        ? '"' + conDescuento[0].nombre + '"'
        : conDescuento.length + ' ítems') +
      '. Tu tope es ' + DESCUENTO_MAXIMO + '%.'
  );
}

// 3. Monto muy por encima de lo que este cliente suele comprar.
if (historial.length >= MINIMO_HISTORIAL && promedio > 0) {
  const veces = f.total / promedio;
  if (veces >= VECES_SOBRE_EL_PROMEDIO) {
    alertas.push(
      'Vale ' + veces.toFixed(1) + ' veces lo que este cliente suele comprar (' +
        plata(promedio) + ' en promedio de ' + historial.length + ' facturas).'
    );
  }
}

// 4. Cliente sin historial y monto alto.
if (historial.length === 0 && f.total >= TOPE_CLIENTE_NUEVO) {
  alertas.push(
    'Es la primera factura de este cliente y ya va por ' + plata(f.total) + '.'
  );
}

// 5. Factura sin ítems o en cero.
if (!f.lineas.length) {
  alertas.push('La factura no tiene ítems.');
} else if (!(f.total > 0)) {
  alertas.push('La factura quedó en cero.');
}

// 6. Vence antes de emitirse. Casi siempre es un dedazo en la fecha.
const emitida = fecha(f.fecha);
const vence = fecha(f.vence);
if (emitida && vence && vence < emitida) {
  alertas.push('La fecha de vencimiento (' + f.vence + ') es anterior a la de emisión (' + f.fecha + ').');
}

const hayAlerta = alertas.length > 0;

let mensaje = '';
if (hayAlerta) {
  mensaje =
    '<b>Revisa esta factura</b>\n\n' +
    '<b>' + f.numero + '</b> — ' + f.cliente + '\n' +
    plata(f.total) + ' · ' + (f.fecha || 'sin fecha') + ' · ' + (f.estado || 'sin estado') + '\n\n' +
    alertas.map((a) => '• ' + a).join('\n') +
    '\n\nNo se cambió nada. Ábrela en Alegra si algo no cuadra.';
}

return [
  {
    json: {
      hayAlerta,
      cantidad: alertas.length,
      alertas,
      mensaje,
      facturaId: f.facturaId,
      numero: f.numero,
      cliente: f.cliente,
      total: f.total,
      promedioCliente: Math.round(promedio),
      facturasAnteriores: historial.length,
    },
  },
];
